-- =============================================================================
-- Quita los datos de demostración (equivalente a php spark demo:limpiar)
-- Solo borra lo creado por demo_funcionamiento.sql (folios, CURP y título fijos).
-- =============================================================================

BEGIN;

CREATE TEMP TABLE _demo_sol ON COMMIT DROP AS SELECT id FROM public.solicitudes WHERE folio IN ('CF6A7A35007F8079ECC3', '10A843D987F8B4ADCB2F', '29B787B116057817C6E6', '35A95ACCC3E42FA220B1', 'D10310D870EE913B5176', '79B0066A9E08F642D821', '6AF6465E79C8DF130A3D', '092B4271758A3DA61DBD', '678B4D9F1BCB53C1443C', 'CBCD0B85513BE6C07548', '7C048891F54471A006DF', 'E6646DF5FB842B41D671', '5DB02605E0B8C72E62CF', '71BEC6F4B3A730C2A610', '75CB82CE51532FBA8E1C', 'A5AF7671A4D06BBCC910', '9CE3C0416786EDD9307C', 'B849FEE7B6E05CC3B802', 'DFEC3056207FB7A949D4', 'DF3D160D4C7CB6DC69E0', 'B86AAA21C50EB1927357', 'DE2C59C93BC32C741AFD', '78EDE5AB0DE06582A789', '00756351708952DD25C4');
-- Cobros de las solicitudes demo (la tabla existe desde la migración 0012).
DO $$ BEGIN
    IF to_regclass('public.cobros') IS NOT NULL THEN
        DELETE FROM public.cobros WHERE solicitud_id IN (SELECT id FROM _demo_sol);
    END IF;
END $$;
DELETE FROM public.historial_estatus WHERE solicitud_id IN (SELECT id FROM _demo_sol);
DELETE FROM public.solicitud_datos WHERE solicitud_id IN (SELECT id FROM _demo_sol);
DELETE FROM public.documentos WHERE solicitud_id IN (SELECT id FROM _demo_sol);
DELETE FROM public.verificaciones_fisicas WHERE solicitud_id IN (SELECT id FROM _demo_sol);
DELETE FROM public.solicitudes WHERE id IN (SELECT id FROM _demo_sol);

-- Ciudadanos demo, solo si ya no tienen otras solicitudes.
CREATE TEMP TABLE _demo_users ON COMMIT DROP AS SELECT u.id FROM public.users u WHERE u.curp IN ('RAGL880214MGTMRR03', 'MOSJ790611HGTRNN08', 'TOVA920830MGTRLN05', 'GUPE850107HGTTRD01', 'HEMM950322MGTRRR09', 'LOCR810915HGTPHB02', 'VEGS900428MGTLRF06', 'CAMD870703HGTSRV04', 'ROJP930119MGTDMT07', 'BASM760925HGTTTG03')
  AND NOT EXISTS (SELECT 1 FROM public.solicitudes s WHERE s.ciudadano_id = u.id);
DELETE FROM public.user_roles WHERE user_id IN (SELECT id FROM _demo_users);
DELETE FROM public.users WHERE id IN (SELECT id FROM _demo_users);

CREATE TEMP TABLE _demo_bol ON COMMIT DROP AS SELECT id FROM public.boletas_infracciones WHERE folio IN ('BOLETA-URI-2026-AGT204-76D5B40C-1', 'BOLETA-URI-2026-AGT204-88B10D39-2', 'BOLETA-URI-2026-AGT204-7C43AF31-3', 'BOLETA-URI-2026-AGT204-411C7CCA-4', 'BOLETA-URI-2026-AGT204-4A3823EE-5', 'BOLETA-URI-2026-AGT204-FA9FE264-6', 'BOLETA-URI-2026-AGT204-C5969156-7', 'BOLETA-URI-2026-AGT204-77094146-8', 'BOLETA-URI-2026-AGT204-447112F1-9', 'BOLETA-URI-2026-AGT204-7E3AB8BC-a', 'BOLETA-URI-2026-AGT204-71C2CBE3-b', 'BOLETA-URI-2026-AGT204-93CC29BD-c', 'BOLETA-URI-2026-AGT204-C6D4E5FD-d', 'BOLETA-URI-2026-AGT204-527101AD-e', 'BOLETA-URI-2026-AGT204-FC47C3E5-f', 'BOLETA-URI-2026-AGT204-7E64B528-g', 'BOLETA-URI-2026-AGT204-3F897473-h', 'BOLETA-URI-2026-AGT204-2EC2A520-i', 'BOLETA-URI-2026-AGT204-6A3CE9B3-j', 'BOLETA-URI-2026-AGT204-7C02E72B-k', 'BOLETA-URI-2026-AGT204-18C1B444-l', 'BOLETA-URI-2026-AGT204-DC318E98-m', 'BOLETA-URI-2026-AGT204-9A9ABCD8-n', 'BOLETA-URI-2026-AGT204-1D4EE4C6-o', 'BOLETA-URI-2026-AGT204-4A780B2C-p', 'BOLETA-URI-2026-AGT204-02FF710A-q', 'BOLETA-URI-2026-AGT107-76D5B40C-1', 'BOLETA-URI-2026-AGT107-88B10D39-2', 'BOLETA-URI-2026-AGT107-7C43AF31-3', 'BOLETA-URI-2026-AGT107-411C7CCA-4', 'BOLETA-URI-2026-AGT107-4A3823EE-5', 'BOLETA-URI-2026-AGT107-FA9FE264-6', 'BOLETA-URI-2026-AGT107-C5969156-7', 'BOLETA-URI-2026-AGT107-77094146-8', 'BOLETA-URI-2026-AGT107-447112F1-9', 'BOLETA-URI-2026-AGT107-7E3AB8BC-a', 'BOLETA-URI-2026-AGT107-71C2CBE3-b', 'BOLETA-URI-2026-AGT107-93CC29BD-c', 'BOLETA-URI-2026-AGT107-C6D4E5FD-d', 'BOLETA-URI-2026-AGT107-527101AD-e', 'BOLETA-URI-2026-AGT107-FC47C3E5-f', 'BOLETA-URI-2026-AGT107-7E64B528-g', 'BOLETA-URI-2026-AGT107-3F897473-h', 'BOLETA-URI-2026-AGT107-2EC2A520-i', 'BOLETA-URI-2026-AGT107-6A3CE9B3-j', 'BOLETA-URI-2026-AGT107-7C02E72B-k', 'BOLETA-URI-2026-AGT107-18C1B444-l', 'BOLETA-URI-2026-AGT107-DC318E98-m', 'BOLETA-URI-2026-AGT107-9A9ABCD8-n', 'BOLETA-URI-2026-AGT107-1D4EE4C6-o', 'BOLETA-URI-2026-AGT107-4A780B2C-p', 'BOLETA-