DO $$ BEGIN
    IF to_regclass('public.cobros') IS NOT NULL THEN
        DELETE FROM public.cobros WHERE boleta_id IN (SELECT id FROM _demo_bol);
    END IF;
END $$;
DELETE FROM public.boletas_infracciones WHERE id IN (SELECT id FROM _demo_bol);

DELETE FROM public.convocatorias c WHERE c.titulo = 'Convocatoria 2026 · Transporte público colectivo'
  AND NOT EXISTS (SELECT 1 FROM public.solicitudes s WHERE s.convocatoria_id = c.id);

COMMIT;
